// GSIM command-driving harness for the Gemmini accelerator -- accelerator-only M2.
//
// Unlike gsim_gemmini_harness.cpp (which drives NOTHING and therefore sits idle),
// this harness drives a VALID gemmini RoCC command stream on io.cmd so the
// controllers leave state 0 and produce a real M2 occupancy waterfall.
//
// The command stream (config_ex + preload + compute) is generated by
// gsim_gemmini_cmd_encode.py into gemmini_cmd_stream.h. It is DRAM-free (no
// mvin/mvout) so no DMA request is issued and the design's TLB assertion never
// fires -- the wall the prior work hit with a memory-touching kernel.
//
// io.cmd setter names (from the generated Gemmini.h -- a RoCC DecoupledIO bundle):
//   set_io$$cmd$$valid(uint8)
//   set_io$$cmd$$bits$$inst$$funct(uint8)   set_io$$cmd$$bits$$inst$$opcode(uint8)
//   set_io$$cmd$$bits$$inst$$xd/xs1/xs2/rd/rs1/rs2(uint8)
//   set_io$$cmd$$bits$$rs1(uint64)          set_io$$cmd$$bits$$rs2(uint64)
//   get_io$$cmd$$ready() -> uint8           (handshake: fire == valid && ready)
//
// Vector IO accessors repaired by gsim_fix_vector_io.py; codegen defects worked
// around by gsim_fix_gemmini_codegen.py.
#include "Gemmini.h"
#include "gemmini_cmd_stream.h"
#include <cstdio>

static void drive_cmd_bits(SGemmini* dut, const GemminiCmd& c) {
  dut->set_io$$cmd$$bits$$inst$$funct(c.funct);
  dut->set_io$$cmd$$bits$$inst$$opcode(c.opcode);
  dut->set_io$$cmd$$bits$$inst$$xd(c.xd);
  dut->set_io$$cmd$$bits$$inst$$xs1(c.xs1);
  dut->set_io$$cmd$$bits$$inst$$xs2(c.xs2);
  dut->set_io$$cmd$$bits$$inst$$rd(0);
  dut->set_io$$cmd$$bits$$inst$$rs1(0);
  dut->set_io$$cmd$$bits$$inst$$rs2(0);
  dut->set_io$$cmd$$bits$$rs1(c.rs1);
  dut->set_io$$cmd$$bits$$rs2(c.rs2);
}

static void clear_valid(SGemmini* dut) {
  dut->set_io$$cmd$$valid(0);
}

// Emit one CSV row for the current (post-step) register state.
static void row(SGemmini* dut, const char* phase, int cyc) {
  printf("%s,%d,%u,%u,%u,%u,%u\n", phase, cyc,
    (unsigned)dut->ex_controller$control_state,
    (unsigned)dut->load_controller$control_state,
    (unsigned)dut->store_controller$control_state,
    (unsigned)dut->get_io$$busy(),
    (unsigned)dut->reservation_station$_io_busy_T_4);
}

int main() {
  SGemmini* dut = new SGemmini();
  int gcyc = 0;  // global cycle counter (post-reset)

  printf("phase,cycle,ex_state,load_state,store_state,io_busy,rs_busy_T4\n");

  // --- reset window ---
  dut->set_reset(1);
  clear_valid(dut);
  for (int c = 0; c < 8; c++) dut->step();
  dut->set_reset(0);

  // Settle a few idle cycles so we can see the pre-drive baseline (all state 0).
  for (int c = 0; c < 3; c++) { dut->step(); row(dut, "idle_pre", gcyc++); }

  // --- drive the command stream, respecting the ready handshake ---
  for (int i = 0; i < GEMMINI_NCMDS; i++) {
    const GemminiCmd& c = GEMMINI_CMDS[i];
    drive_cmd_bits(dut, c);
    dut->set_io$$cmd$$valid(1);
    int fired = 0;
    for (int wait = 0; wait < 64 && !fired; wait++) {
      dut->step();
      unsigned ready = dut->get_io$$cmd$$ready();
      row(dut, c.name, gcyc++);
      if (ready) fired = 1;   // valid&&ready this cycle -> command enqueued
    }
    clear_valid(dut);
    // one settle cycle with valid low before the next command
    dut->step(); row(dut, "gap", gcyc++);
  }
  clear_valid(dut);

  // --- observe the controllers draining after the stream ---
  for (int c = 0; c < 60; c++) { dut->step(); row(dut, "drain", gcyc++); }

  delete dut;
  return 0;
}
